"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import time

from app.config import CACHE_PATH, CACHE_TTL


def get_or_load(key, loader, now=None):
    """Return cached value for *key* while fresh, else call *loader* and store.

    The cache file at CACHE_PATH is a JSON object mapping keys to
    ``{"stored_at": <epoch_float>, "value": <profile_dict>}``.
    A cached entry is valid while ``now - stored_at < CACHE_TTL``.
    """
    if now is None:
        now = time.time()

    store = _read_store()

    if key in store:
        entry = store[key]
        if now - entry["stored_at"] < CACHE_TTL:
            return entry["value"]

    value = loader()
    store[key] = {"stored_at": now, "value": value}
    _write_store(store)
    return value


def _read_store():
    """Load the JSON store from disk, returning {} on any problem."""
    try:
        with open(CACHE_PATH, "r") as fh:
            return json.load(fh)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return {}


def _write_store(store):
    """Atomically write *store* to CACHE_PATH, creating dirs as needed."""
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, "w") as fh:
        json.dump(store, fh)

